package com.mahesh.empleave.leavebalance;import com.mahesh.empleave.leave.*;import com.mahesh.empleave.user.AppUser;import org.springframework.data.domain.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import java.time.*;import java.util.*;public interface BalanceTransactionRepository extends JpaRepository<BalanceTransaction,Long>{boolean existsByApplication(LeaveApplication application);List<BalanceTransaction> findByBalanceUser(AppUser user);@Query("select t from BalanceTransaction t where t.balance.user=:user and (:type is null or t.reason=:type) and (:start is null or t.createdAt>=:start) and (:end is null or t.createdAt<:end)") Page<BalanceTransaction> filtered(@Param("user") AppUser user,@Param("type") String type,@Param("start") LocalDateTime start,@Param("end") LocalDateTime end,Pageable pageable);}
